SELECT * FROM ai_parse_log 
WHERE teacher_id = #{teacherId} 
ORDER BY create_time DESC

SELECT * FROM ai_parse_log 
WHERE confidence_score BETWEEN #{minScore} AND #{maxScore}
ORDER BY create_time DESC

